1	import { clientscript } from "../generated/clientscript"
2	import { ClientscriptObfuscation } from "./callibrator";
3	import { ClientScriptOp, StackDiff, StackList, SwitchJumpTable, branchInstructions, getParamOps, knownClientScriptOpNames, longBigIntToJson, longJsonToBigInt, namedClientScriptOps, typeToPrimitive } from "./definitions"
4	import { rs3opnames } from "./opnames";
5	import { CS2Api, MAGIC_CONST_CURRENTCOMP, UiRenderContext } from "../scripts/renderrsinterface";
6	import { cacheMajors } from "../constants";
7	import { parse } from "../opdecoder";
8	import { getEnumInt, getStructInt, loadEnum, loadStruct } from "./util";
9	
10	
11	type ScriptScope = {
12	    scriptid: number;
13	    index: number;
14	    ops: ClientScriptOp[];
15	    switches: SwitchJumpTable[];
16	    localints: number[];
17	    locallongs: bigint[];
18	    localstrings: string[];
19	}
20	
21	type InterpreterWithScope = ClientScriptInterpreter & { scope: ScriptScope };
22	type OpImplementation = (inter: InterpreterWithScope, op: ClientScriptOp) => void | Promise<void>;
23	
24	export class ClientScriptInterpreter {
25	    intstack: number[] = [];
26	    longstack: bigint[] = [];
27	    stringstack: string[] = [];
28	    scopeStack: ScriptScope[] = [];
29	    calli: ClientscriptObfuscation;
30	    mockscripts = new Map<number, (number | bigint | string)[]>();
31	    scope: ScriptScope | null = null;
32	    activecompid = -1;
33	    clientcomps: (CS2Api | undefined)[] = [undefined, undefined];
34	    stalled: Promise<boolean> | void = undefined;
35	    uictx: UiRenderContext | null = null;
36	    constructor(calli: ClientscriptObfuscation, uictx: UiRenderContext | null = null) {
37	        this.calli = calli;
38	        this.uictx = uictx;
39	    }
40	    reset() {
41	        if (this.stalled) {
42	            console.log("resetting cs2 interpreter while an async op is running, everything is probably corrupt");
43	        }
44	        this.scopeStack.length = 0;
45	        this.scope = null;
46	        this.intstack.length = 0;
47	        this.longstack.length = 0;
48	        this.stringstack.length = 0;
49	        this.activecompid = -1;
50	        this.clientcomps.fill(undefined);
51	    }
52	    popComponent() {
53	        return this.getComponent(this.popint());
54	    }
55	    getClientComp(imm: number) {
56	        const comp = this.clientcomps[imm];
57	        if (!comp) { throw new Error(`clientcomp not set`); }
58	        return comp;
59	    }
60	    getComponent(compid: number) {
61	        if ((compid | 0) == MAGIC_CONST_CURRENTCOMP) { compid = this.activecompid; }
62	        const comp = this.uictx?.comps.get(compid);
63	        if (!comp) { return new CS2Api(null); }
64	        return comp.api;
65	    }
66	    async callscriptid(id: number) {
67	        const data = await this.calli.source.getFileById(cacheMajors.clientscript, id);
68	        this.callscript(parse.clientscript.read(data, this.calli.source), id);
69	    }
70	    async runToEnd() {
71	        while (true) {
72	            let res = this.next();
73	            if (res instanceof Promise) {
74	                res = await res;
75	            }
76	            if (!res) { break; }
77	        }
78	    }
79	    callscript(script: clientscript, scriptid: number) {
80	        this.log(`calling script ${scriptid}`);
81	        this.scope = {
82	            scriptid: scriptid,
83	            index: 0,
84	            ops: script.opcodedata,
85	            switches: script.switches,
86	            localints: new Array(script.localintcount).fill(0),
87	            locallongs: new Array(script.locallongcount).fill(0n),
88	            localstrings: new Array(script.localstringcount).fill("")
89	        };
90	        for (let i = script.intargcount - 1; i >= 0; i--) { this.scope.localints[i] = this.popint(); }
91	        for (let i = script.longargcount - 1; i >= 0; i--) { this.scope.locallongs[i] = this.poplong(); }
92	        for (let i = script.stringargcount - 1; i >= 0; i--) { this.scope.localstrings[i] = this.popstring(); }
93	        this.scopeStack.push(this.scope);
94	    }
95	
96	    log(text: string) {
97	        console.log(`CS2: ${"  ".repeat(this.scopeStack.length)} ${text}`);
98	    }
99	    pushStackdiff(diff: StackDiff) {
100	        if (diff.vararg != 0) { throw new Error("cannot push vararg"); }
101	        for (let i = 0; i < diff.int; i++) { this.pushint(0); }
102	        for (let i = 0; i < diff.long; i++) { this.pushlong(0n); }
103	        for (let i = 0; i < diff.string; i++) { this.pushstring(""); }
104	    }
105	    popStacklist(list: StackList) {
106	        for (let i = list.values.length - 1; i >= 0; i--) {
107	            const val = list.values[i];
108	            if (val instanceof StackDiff) { this.popStackdiff(val); }
109	            else if (val == "int") { this.popint(); }
110	            else if (val == "long") { this.poplong(); }
111	            else if (val == "string") { this.popstring(); }
112	            else if (val == "vararg") { this.popvararg(); }
113	            else { throw new Error("unexpected"); }
114	        }
115	    }
116	    popvararg() {
117	        const str = this.popstring();
118	        for (let i = str.match(/Y/g)?.length ?? 0; i > 0; i--) { for (let ii = this.popint(); ii > 0; ii--) { this.popint(); } }
119	        for (let i = str.match(/i/g)?.length ?? 0; i > 0; i--) { this.popint(); }
120	        for (let i = str.match(/l/g)?.length ?? 0; i > 0; i--) { this.poplong(); }
121	        for (let i = str.match(/s/g)?.length ?? 0; i > 0; i--) { this.popstring(); }
122	    }
123	    popStackdiff(diff: StackDiff) {
124	        if (diff.vararg != 0) { throw new Error("can't pop vararg since the order of pops is ambiguous"); }
125	        for (let i = 0; i < diff.int; i++) { this.popint(); }
126	        for (let i = 0; i < diff.long; i++) { this.poplong(); }
127	        for (let i = 0; i < diff.string; i++) { this.popstring(); }
128	    }
129	    //shorthand for unordered stack access in implementation
130	    popdeep(depth: number) {
131	        if (this.intstack.length < depth) { throw new Error(`tried to pop int while none are on stack at index ${(this.scope?.index ?? 0) - 1}`); }
132	        return this.intstack.splice(this.intstack.length - 1 - depth, 1)[0];
133	    }
134	    //shorthand for unordered stack access in implementation
135	    popdeeplong(depth: number) {
136	        if (this.longstack.length < depth) { throw new Error(`tried to pop long while none are on stack at index ${(this.scope?.index ?? 0) - 1}`); }
137	        return this.longstack.splice(this.longstack.length - 1 - depth, 1)[0];
138	    }
139	    //shorthand for unordered stack access in implementation
140	    popdeepstr(depth: number) {
141	        if (this.stringstack.length < depth) { throw new Error(`tried to pop string while none are on stack at index ${(this.scope?.index ?? 0) - 1}`); }
142	        return this.stringstack.splice(this.stringstack.length - 1 - depth, 1)[0];
143	    }
144	    popint() {
145	        if (this.intstack.length == 0) { throw new Error(`tried to pop int while none are on stack at index ${(this.scope?.index ?? 0) - 1}`); }
146	        return this.intstack.pop()!;
147	    }
148	    poplong() {
149	        if (this.longstack.length == 0) { throw new Error(`tried to pop long while none are on stack at index ${(this.scope?.index ?? 0) - 1}`); }
150	        return this.longstack.pop()!;
151	    }
152	    popstring() {
153	        if (this.stringstack.length == 0) { throw new Error(`tried to pop string while none are on stack at index ${(this.scope?.index ?? 0) - 1}`); }
154	        return this.stringstack.pop()!;
155	    }
156	    pushlist(list: (number | bigint | string)[]) {
157	        for (const v of list) {
158	            if (typeof v == "number") { this.pushint(v); }
159	            else if (typeof v == "bigint") { this.pushlong(v); }
160	            else if (typeof v == "string") { this.pushstring(v); }
161	            else { throw new Error("unexpected"); }
162	        }
163	    }
164	    pushint(v: number) { this.intstack.push(v); }
165	    pushlong(v: bigint) { this.longstack.push(v); }
166	    pushstring(v: string) { this.stringstack.push(v); }
167	    next(): boolean | Promise<boolean> {
168	        if (this.stalled) { return this.stalled = this.stalled.then(res => res && this.next()); }
169	        if (!this.scope) { throw new Error("no script"); }
170	        if (this.scope.index < 0 || this.scope.index >= this.scope.ops.length) {
171	            throw new Error("jumped out of bounds");
172	        }
173	        const op = this.scope.ops[this.scope.index++];
174	        let implemented = implementedops.get(op.opcode);
175	        if (!implemented) {
176	            //TODO create a proper way to deal with "not-quite-named" ops
177	            //try find raw op name
178	            for (const [id, name] of Object.entries(rs3opnames)) {
179	                if (+id == op.opcode) {
180	                    implemented = namedimplementations.get(name);
181	                    break;
182	                }
183	            }
184	        }
185	        let res: Promise<void> | void = undefined;
186	        if (op.opcode == namedClientScriptOps.return) {
187	            this.scopeStack.pop();
188	            this.scope = this.scopeStack.at(-1) ?? null;
189	            return !!this.scope;
190	        } else if (implemented) {
191	            res = implemented(this as InterpreterWithScope, op);
192	        } else {
193	            const opinfo = this.calli.decodedMappings.get(op.opcode);
194	            if (!opinfo) { throw new Error(`Uknown op with opcode ${op.opcode}`); }
195	            if (!opinfo.stackinfo.initializedthrough) { throw new Error(`Unknown params/returns for op ${op.opcode}`); }
196	            this.popStacklist(opinfo.stackinfo.in);
197	            this.pushStackdiff(opinfo.stackinfo.out.toStackDiff());
198	        }
199	
200	        if (res instanceof Promise) {
201	            this.stalled = res.finally(() => this.stalled = undefined).then(q => true).catch(q => false);
202	            return this.stalled;
203	        } else {
204	            return true;
205	        }
206	    }
207	    dump() {
208	        let res = "";
209	        res += "locals:\n";
210	        res += `${this.scope?.localints.join(",") ?? "no scope"}\n`;
211	        res += `${this.scope?.locallongs.join(",") ?? "no scope"}\n`;
212	        res += `${this.scope?.localstrings.map(q => `"${q}"`).join(",") ?? "no scope"}\n`;
213	        res += "stack:\n";
214	        res += `${this.intstack.join(",")}\n`;
215	        res += `${this.longstack.join(",")}\n`;
216	        res += `${this.stringstack.map(q => `"${q}"`).join(",")}\n`;
217	        if (this.scope) {
218	            res += `script stack ${this.scopeStack.map(q => q.scriptid).join(", ")}\n`;
219	            for (let i = -5; i < 10; i++) {
220	                const index = this.scope.index + i;
221	                if (index < 0 || index >= this.scope.ops.length) { continue; }
222	                res += `${index} ${index == this.scope.index ? ">>" : "  "} `;
223	                const op = this.scope.ops[index];
224	                if (op) {
225	                    const opinfo = this.calli.decodedMappings.get(op.opcode);
226	                    const name = knownClientScriptOpNames[op.opcode];
227	                    res += `${name.padEnd(12, " ").slice(0, 12)} ${op.imm} ${op.imm_obj ?? ""}\n`;
228	                } else {
229	                    res += `??\n`;
230	                }
231	            }
232	        }
233	        console.log(res);
234	    }
235	}
