238	function branchOp(inter: ClientScriptInterpreter, op: ClientScriptOp) {
239	    let result = false;
240	    if (op.opcode == namedClientScriptOps.branch_eq) { result = inter.popdeep(1) == inter.popdeep(0); }
241	    else if (op.opcode == namedClientScriptOps.branch_not) { result = inter.popdeep(1) != inter.popdeep(0); }
242	    else if (op.opcode == namedClientScriptOps.branch_lt) { result = inter.popdeep(1) < inter.popdeep(0); }
243	    else if (op.opcode == namedClientScriptOps.branch_lteq) { result = inter.popdeep(1) <= inter.popdeep(0); }
244	    else if (op.opcode == namedClientScriptOps.branch_gt) { result = inter.popdeep(1) > inter.popdeep(0); }
245	    else if (op.opcode == namedClientScriptOps.branch_gteq) { result = inter.popdeep(1) >= inter.popdeep(0); }
246	    else { throw new Error("unknown branch op (branch long not implemented)"); }
247	    // else if (op.opcode == namedClientScriptOps.branch_eq_long) { result = inter.popint() == inter.popint(); }
248	    // else if (op.opcode == namedClientScriptOps.branch_not_long) { result = inter.popint() != inter.popint(); }
249	    // else if (op.opcode == namedClientScriptOps.branch_lt_long) { result = inter.popint() < inter.popint(); }
250	    // else if (op.opcode == namedClientScriptOps.branch_lteq_long) { result = inter.popint() <= inter.popint(); }
251	    // else if (op.opcode == namedClientScriptOps.branch_gt_long) { result = inter.popint() > inter.popint(); }
252	    // else if (op.opcode == namedClientScriptOps.branch_gteq_long) { result = inter.popint() <= inter.popint(); }
253	    if (result) {
254	        if (!inter.scope) { throw new Error("unexpected"); }
255	        inter.scope.index += op.imm;
256	    }
257	}
