99	export function augmentZOffsetMaterial(mat: THREE.Material, zoffset: number) {
100		mat.customProgramCacheKey = () => "zoffset" + zoffset;
101		mat.onBeforeCompile = (shader) => {
102			shader.vertexShader = shader.vertexShader.replace(/#include <(\w+)>/g, (m, n) => `// == ${n} ==\n${m}`);
103			shader.vertexShader = shader.vertexShader.replace("#include <project_vertex>", `
104				#include <project_vertex>
105				mvPosition.xyz -= normalize(mvPosition.xyz) * ${zoffset.toExponential()};
106				gl_Position = projectionMatrix * mvPosition;
107			`);
108		};
109	}
