229		private async preload() {
230			if (this.getBuildNr() > lastLegacyBuildnr) {
231				for (const subfile of await this.getArchiveById(cacheMajors.config, cacheConfigPages.mapunderlays)) {
232					this.mapUnderlays[subfile.fileid] = parse.mapsquareUnderlays.read(subfile.buffer, this.rawsource);
233				}
234				for (const subfile of await this.getArchiveById(cacheMajors.config, cacheConfigPages.mapoverlays)) {
235					this.mapOverlays[subfile.fileid] = parse.mapsquareOverlays.read(subfile.buffer, this.rawsource);
236				}
237	
238				if (this.getBuildNr() >= 527) {
239					for (const subfile of await this.getArchiveById(cacheMajors.config, cacheConfigPages.mapscenes)) {
240						this.mapMapscenes[subfile.fileid] = parse.mapscenes.read(subfile.buffer, this.rawsource);
241					}
242				}
243				if (this.getBuildNr() >= 548) {
244					for (const subfile of await this.getArchiveById(cacheMajors.config, cacheConfigPages.maplabels)) {
245						this.mapMaplabels[subfile.fileid] = parse.maplabels.read(subfile.buffer, this.rawsource);
246					}
247				}
248	
249				if (this.getBuildNr() <= 471) {
250					for (const file of await this.getArchiveById(cacheMajors.texturesOldPng, 0)) {
251						this.materialArchive.set(file.fileid, file.buffer);
252					}
253				} else if (this.getBuildNr() <= 498) {
254					//no material data
255				} else if (this.getBuildNr() <= 753) {
256					const file = await this.getFile(cacheMajors.materials, 0);
257					this.materialArchive.set(0, file);
258				} else {
259					for (const file of await this.getArchiveById(cacheMajors.materials, 0)) {
260						this.materialArchive.set(file.fileid, file.buffer);
261					}
262				}
263	
264				const rootindex = await this.getCacheIndex(cacheMajors.index);
265				this.hasNewModels = !!rootindex[cacheMajors.models];
266				this.hasOldModels = !!rootindex[cacheMajors.oldmodels];
267			} else if (this.getBuildNr() > lastClassicBuildnr) {
268				this.legacyData = await legacyPreload(this);
269				const floors = this.legacyData.overlays.map(q => parse.mapsquareOverlays.read(q, this));
270				this.mapOverlays = floors;
271				this.mapUnderlays = floors;
272	
273				this.hasNewModels = false;
274				this.hasOldModels = true;
275			} else {
276				if (!(this.rawsource instanceof ClassicFileSource)) {
277					throw new Error("can only load classic caches from a classic source");
278				}
279				this.classicData = await classicConfig(this.rawsource, this.getBuildNr());
280				this.mapUnderlays = classicUnderlays();
281				this.mapOverlays = await classicOverlays(this);
282				this.hasNewModels = false;
283				this.hasOldModels = true;
284			}
285	
286			return this;
287		}
