302		getMaterialData(id: number) {
303			let cached = this.materialCache.get(id);
304			if (!cached) {
305				if (id == -1) {
306					cached = defaultMaterial();
307				} else {
308					if (this.getBuildNr() <= lastLegacyBuildnr) {
309						cached = defaultMaterial();
310						cached.textures.diffuse = id;
311						cached.baseColorFraction = 1;
312						cached.texmodes = "mirror";
313						cached.texmodet = "mirror";
314					} else if (this.getBuildNr() <= 471) {
315						const file = this.materialArchive.get(id);
316						if (!file) { throw new Error("material " + id + " not found"); }
317						const matprops = parse.oldproctexture.read(file, this);
318						cached = defaultMaterial();
319						cached.textures.diffuse = matprops.spriteid;
320						cached.baseColorFraction = 1;
321					} else if (this.getBuildNr() <= 753) {
322						cached = defaultMaterial();
323						if (this.getBuildNr() >= 500) {
324							const matlist = parse.oldmaterials.read(this.materialArchive.get(0)!, this);
325							const matdata = matlist.mats[id];
326							//builds 736-759 tecnically do have usable textures, this depends on scenecache.texturemode!="none"
327							//textures should be moved to enginecache
328							// cached.textures.diffuse = id;
329							if (matdata.basecolorfraction != null && matdata.basecolor != null) {
330								cached.baseColorFraction = matdata.basecolorfraction / 255;
331								cached.baseColor = HSL2RGBfloat(packedHSL2HSL(matdata.basecolor));
332							}
333							cached.textures.diffuse = matdata.id;
334							//TODO other material props
335						}
336					} else {
337						const file = this.materialArchive.get(id);
338						if (!file) { throw new Error("material " + id + " not found"); }
339						cached = convertMaterial(file, id, this.rawsource);
340					}
341				}
342				this.materialCache.set(id, cached);
343			}
344			return cached;
345		}
