347		/**
348		 * very aggressive caching, do not use for objects which take a lot of memory
349		 */
350		getJsonSearchData(modename: string) {
351			let cached = this.jsonSearchCache.get(modename);
352			if (!cached) {
353				const mode = cacheFileJsonModes[modename as keyof typeof cacheFileJsonModes];
354				if (!mode) { throw new Error("unknown decode mode " + modename); }
355				const files = (async () => {
356					await mode.prepareDump?.(this);
357					const allfiles = await mode.lookup.logicalRangeToFiles(this, [0, 0], [Infinity, Infinity]);
358					let lastarchive: null | { index: CacheIndex, subfiles: SubFile[] } = null;
359					const files: any[] = [];
360					for (const fileid of allfiles) {
361						let arch: SubFile[];
362						if (lastarchive && lastarchive.index == fileid.index) {
363							arch = lastarchive.subfiles;
364						} else {
365							arch = await this.getFileArchive(fileid.index);
366							lastarchive = { index: fileid.index, subfiles: arch };
367						}
368						const file = arch[fileid.subindex];
369						const logicalid = mode.lookup.fileToLogical(this, fileid.index.major, fileid.index.minor, file.fileid);
370						const res = mode.parser.read(file.buffer, this.rawsource);
371						res.$fileid = (logicalid.length == 1 ? logicalid[0] : logicalid);
372						files.push(res);
373					}
374	
375					return files;
376				})();
377				cached = { files, schema: mode.parser.parser.getJsonSchema() }
378				this.jsonSearchCache.set(modename, cached);
379			}
380			return cached;
381		}
382	}
