384	export async function* iterateConfigFiles(cache: EngineCache, major: number) {
385		if (cache.legacyData) {
386			let files: Buffer[] | null = null;
387			if (major == cacheMajors.items) { files = cache.legacyData.items; }
388			else if (major == cacheMajors.npcs) { files = cache.legacyData.npcs; }
389			else if (major == cacheMajors.objects) { files = cache.legacyData.objects; }
390			else if (major == cacheMajors.spotanims) { files = cache.legacyData.spotanims; }
391			if (!files) { throw new Error(`cache major ${major} can not be iterated`); }
392			yield* files.map((file, id) => ({ id, file }));
393		} else if (cache.getBuildNr() <= 488) {
394			const arch = await cache.getArchiveById(cacheMajors.config, oldConfigMaps[major]);
395			yield* arch.map(q => ({ id: q.fileid, file: q.buffer }));
396		} else {
397			const locindices = await cache.getCacheIndex(major);
398			const stride = mappedFileIds[major];
399			for (const index of locindices) {
400				if (!index) { continue; }
401				const arch = await cache.getFileArchive(index);
402				yield* arch.map(q => ({ id: index.minor * stride + q.fileid, file: q.buffer }));
403			}
404		}
405	}
