407	export async function detectTextureMode(source: CacheFileSource) {
408		const detectmajor = async (major: number) => {
409			let lastfile = -1;
410			try {
411				const indexfile = await source.getCacheIndex(major);
412				const last = indexfile[indexfile.length - 1];
413				await source.getFile(last.major, last.minor, last.crc);
414				lastfile = last.minor;
415			} catch (e) { }
416			return lastfile;
417		}
418	
419		let textureMode: TextureModes = "none";
420		if (source.getBuildNr() <= lastClassicBuildnr) {
421			const texindex = await source.findSubfileByName(0, classicGroups.textures, "INDEX.DAT");
422			textureMode = (texindex ? "legacy" : "legacytga");
423		} else if (source.getBuildNr() <= lastLegacyBuildnr) {
424			textureMode = "legacy";
425		} else if (source.getBuildNr() <= 471) {
426			textureMode = "oldproc";
427		} else if (source.getBuildNr() <= 736) {
428			textureMode = "fullproc";//uses old procedural textures in index 9
429		} else {
430			const numbmp = await detectmajor(cacheMajors.texturesBmp);
431			const numdds = await detectmajor(cacheMajors.texturesDds);
432			if (numbmp > 0 || numdds > 0) {
433				textureMode = (numbmp > numdds ? "bmp" : "dds");
434			} else {
435				const numpng2014 = await detectmajor(cacheMajors.textures2015Png);
436				const numdds2014 = await detectmajor(cacheMajors.textures2015Dds);
437				if (numpng2014 > 0 || numdds2014 >= 0) {
438					textureMode = (numdds2014 > numpng2014 ? "dds2014" : "png2014");
439				} else if (await detectmajor(cacheMajors.texturesOldPng) > 0) {
440					textureMode = "oldpng";
441				} else {
442					textureMode = "none";
443				}
444			}
445		}
446		console.log(`detectedtexture mode. ${textureMode}`);
447		return textureMode;
448	}
