450	async function convertMaterialToThree(source: ThreejsSceneCache, material: MaterialData, hasVertexAlpha: boolean, minimapVariant: boolean) {
451		let mat = new THREE.MeshStandardMaterial();
452		mat.alphaTest = (material.alphamode == "cutoff" ? 0.5 : 0.1);//TODO use value from material
453		mat.transparent = hasVertexAlpha || material.alphamode == "blend";
454		const wraptypes = material.texmodes == "clamp" ? THREE.ClampToEdgeWrapping : material.texmodes == "repeat" ? THREE.RepeatWrapping : THREE.MirroredRepeatWrapping;
455		const wraptypet = material.texmodet == "clamp" ? THREE.ClampToEdgeWrapping : material.texmodet == "repeat" ? THREE.RepeatWrapping : THREE.MirroredRepeatWrapping;
456	
457		if (typeof material.textures.diffuse != "undefined" && source.textureType != "none") {
458			const diffuse = await (await source.getTextureFile("diffuse", material.textures.diffuse, material.stripDiffuseAlpha)).toImageData();
459			const difftex = new THREE.DataTexture(diffuse.data, diffuse.width, diffuse.height, THREE.RGBAFormat);
460			difftex.needsUpdate = true;
461			difftex.wrapS = wraptypes;
462			difftex.wrapT = wraptypet;
463			difftex.colorSpace = THREE.SRGBColorSpace;
464			difftex.magFilter = THREE.LinearFilter;
465			difftex.minFilter = THREE.NearestMipMapNearestFilter;
466			difftex.generateMipmaps = true;
467	
468			mat.map = difftex;
469	
470			if (material.textures.normal) {
471				const parsed = await source.getTextureFile("normal", material.textures.normal, false);
472				const raw = await parsed.toImageData();
473				const normals = makeImageData(null, raw.width, raw.height);
474				const emisive = makeImageData(null, raw.width, raw.height);
475				const data = raw.data;
476				for (let i = 0; i < data.length; i += 4) {
477					//normals
478					const dx = data[i + 1] / 127.5 - 1;
479					const dy = data[i + 3] / 127.5 - 1;
480					normals.data[i + 0] = data[i + 1];
481					normals.data[i + 1] = data[i + 3];
482					normals.data[i + 2] = (Math.sqrt(Math.max(1 - dx * dx - dy * dy, 0)) + 1) * 127.5;
483					normals.data[i + 3] = 255;
484					//emisive //TODO check if normals flag always implies emisive
485					const emissive = data[i + 0] / 255;
486					emisive.data[i + 0] = diffuse.data[i + 0] * emissive;
487					emisive.data[i + 1] = diffuse.data[i + 1] * emissive;
488					emisive.data[i + 2] = diffuse.data[i + 2] * emissive;
489					emisive.data[i + 3] = 255;
490				}
491				mat.normalMap = new THREE.DataTexture(normals.data, normals.width, normals.height, THREE.RGBAFormat);
492				mat.normalMap.needsUpdate = true;
493				mat.normalMap.wrapS = wraptypes;
494				mat.normalMap.wrapT = wraptypet;
495				mat.normalMap.magFilter = THREE.LinearFilter;
496	
497				mat.emissiveMap = new THREE.DataTexture(emisive.data, emisive.width, emisive.height, THREE.RGBAFormat);
498				mat.emissiveMap.needsUpdate = true;
499				mat.emissiveMap.wrapS = wraptypes;
500				mat.emissiveMap.wrapT = wraptypet;
501				mat.emissiveMap.magFilter = THREE.LinearFilter;
502				mat.emissive.setRGB(1, 1, 1);
503			}
504			if (material.textures.compound) {
505				const compound = await (await source.getTextureFile("compound", material.textures.compound, false)).toImageData();
506				const compoundmapped = makeImageData(null, compound.width, compound.height);
507				//threejs expects g=metal,b=roughness, rs has r=metal,g=roughness
508				for (let i = 0; i < compound.data.length; i += 4) {
509					compoundmapped.data[i + 1] = compound.data[i + 1];
510					compoundmapped.data[i + 2] = compound.data[i + 0];
511					compoundmapped.data[i + 3] = 255;
512				}
513				const tex = new THREE.DataTexture(compoundmapped.data, compoundmapped.width, compoundmapped.height, THREE.RGBAFormat);
514				tex.needsUpdate = true;
515				tex.wrapS = wraptypes;
516				tex.wrapT = wraptypet;
517				tex.colorSpace = THREE.SRGBColorSpace;
518				tex.magFilter = THREE.LinearFilter;
519				mat.metalnessMap = tex;
520				mat.roughnessMap = tex;
521				mat.metalness = 1;
522			}
523		}
524		mat.vertexColors = material.baseColorFraction != 1 || !material.textures.diffuse || hasVertexAlpha;
525	
526		mat.userData = material;
527		if (material.uvAnim) {
528			(mat.userData.gltfExtensions ??= {}).RA_materials_uvanim = {
529				uvAnim: [material.uvAnim.u, material.uvAnim.v]
530			};
531		}
532		if (minimapVariant) {
533			// augmentThreeJsMinimapLocMaterial(mat);
534			mat = minimapLocMaterial(mat.map!, material.alphamode, material.alphacutoff) as any;
535		}
536	
537		return { mat, matmeta: material };
538	}
