686	export function applyMaterial(mesh: Mesh, parsedmat: ParsedMaterial, minimapVariant: boolean, inplace = false) {
687		const oldcol = mesh.geometry.getAttribute("color");
688		const hasVertexAlpha = !!oldcol && oldcol.itemSize == 4;
689		mesh.material = parsedmat.mat;
690		//TODO what does the minimap do when basecolorfraction!=1, eg:0.8
691		const basecolor = (minimapVariant && parsedmat.matmeta.baseColorFraction == 1 ? [0.5, 0.5, 0.5] : parsedmat.matmeta.baseColor);
692		const nonwhiteverts = parsedmat.matmeta.baseColorFraction != 1 || basecolor.some(q => q != 1) || minimapVariant
693		const needsvertexcolors = nonwhiteverts || !parsedmat.matmeta.textures.diffuse || hasVertexAlpha;
694		if (needsvertexcolors) {
695			if (parsedmat.matmeta.baseColorFraction != 0) {
696				const vertcount = mesh.geometry.getAttribute("position").count;
697				const oldcol = mesh.geometry.getAttribute("color");
698				const oldfrac = 1 - parsedmat.matmeta.baseColorFraction;
699				const newrcomp = parsedmat.matmeta.baseColorFraction * basecolor[0] * 255;
700				const newgcomp = parsedmat.matmeta.baseColorFraction * basecolor[1] * 255;
701				const newbcomp = parsedmat.matmeta.baseColorFraction * basecolor[2] * 255;
702				const itemsize = hasVertexAlpha ? 4 : 3;
703				const newcol = (inplace && oldcol ? oldcol : new BufferAttribute(new Uint8Array(itemsize * vertcount), itemsize, true));
704				if (hasVertexAlpha && !oldcol) {
705					throw new Error("material has vertex alpha, but mesh doesn't have vertex colors");
706				}
707	
708				const [oldbuf, oldoffset, oldstride] = getAttributeBackingStore(oldcol) as [Uint8Array, number, number];
709				const [newbuf, newoffset, newstride] = getAttributeBackingStore(newcol) as [Uint8Array, number, number];
710				const hasoldcol = !!oldcol;
711	
712				for (let i = 0; i < vertcount; i++) {
713					const ii = newoffset + newstride * i;
714					const jj = oldoffset + oldstride * i;
715					const oldr = (hasoldcol ? oldbuf[jj + 0] : 255);
716					const oldg = (hasoldcol ? oldbuf[jj + 1] : 255);
717					const oldb = (hasoldcol ? oldbuf[jj + 2] : 255);
718					newbuf[ii + 0] = clamp(oldr * oldfrac + newrcomp);
719					newbuf[ii + 1] = clamp(oldg * oldfrac + newgcomp);
720					newbuf[ii + 2] = clamp(oldb * oldfrac + newbcomp);
721					if (hasVertexAlpha) {
722						newbuf[ii + 3] = (hasoldcol ? oldbuf[jj + 3] : 255);
723					}
724				}
725				mesh.geometry.setAttribute("color", newcol);
726			}
727		} else if (mesh.geometry.getAttribute("color")) {
728			mesh.geometry.deleteAttribute("color");
729		}
730	}
