732	/**
733	 * When merging player npc models the client incorrectly merge vertices which
734	 * have the same position+color+material, but with different bone ids. The second
735	 * vertex will be merged and its bone id is lost. This bug is so entrenched in
736	 * the game that player models will have detached arms and waist if not replicated
737	 */
738	export function mergeBoneids(model: ModelData) {
739		const totalverts = model.meshes.reduce((a, v) => a + v.vertexend - v.vertexstart, 0);
740		const order = new Uint32Array(totalverts);
741		let orderindex = 0;
742		for (let meshindex = 0; meshindex < model.meshes.length; meshindex++) {
743			const mesh = model.meshes[meshindex];
744			for (let i = mesh.vertexstart; i < mesh.vertexend; i++) {
745				order[orderindex++] = (meshindex << 23) | i;
746			}
747		}
748	
749		function compareVertkeys(model: ModelData, a: number, b: number) {
750			const mesha = model.meshes[a >> 23];
751			const meshb = model.meshes[b >> 23];
752			const ia = a & 0x7fffff;
753			const ib = b & 0x7fffff;
754			const posa = mesha.attributes.pos;
755			const posb = meshb.attributes.pos;
756			return posa.getX(ia) - posb.getX(ib)
757				|| posa.getY(ia) - posb.getY(ib)
758				|| posa.getZ(ia) - posb.getZ(ib);
759		}
760	
761		const tmp1 = new THREE.Vector3();
762		const normsum = new THREE.Vector3();
763		let mergecount = 0;
764		order.sort((a, b) => compareVertkeys(model, a, b));
765		for (let i = 0; i < order.length;) {
766			const start = i;
767			while (i < order.length && compareVertkeys(model, order[start], order[++i]) == 0);
768			if (i > start + 1) {
769				const mesh1 = model.meshes[order[start] >> 23];
770				const i1 = order[start] & 0x7fffff;
771	
772				//calculate blended normal
773				normsum.set(0, 0, 0);
774				for (let j = start; j < i; j++) {
775					const mesh2 = model.meshes[order[j] >> 23];
776					const i2 = order[j] & 0x7fffff;
777	
778					if (mesh2.needsNormalBlending && mesh2.attributes.normals) {
779						tmp1.fromBufferAttribute(mesh2.attributes.normals, i2);
780						normsum.add(tmp1);
781					}
782				}
783				normsum.normalize();
784	
785				for (let j = start; j < i; j++) {
786					const mesh2 = model.meshes[order[j] >> 23];
787					const i2 = order[j] & 0x7fffff;
788	
789					//copy bone id and weights from first vertex
790					if (j != start && mesh1.attributes.boneids && mesh1.attributes.boneweights && mesh2.attributes.boneids && mesh2.attributes.boneweights) {
791						if (mesh1.attributes.boneids.getX(i1) != mesh2.attributes.boneids.getX(i2)) {
792							mergecount++;
793						}
794						mesh2.attributes.boneids.copyAt(i2, mesh1.attributes.boneids, i1);
795						mesh2.attributes.boneweights.copyAt(i2, mesh1.attributes.boneweights, i1);
796					}
797	
798					//write blended normal
799					if (mesh2.needsNormalBlending && mesh2.attributes.normals) {
800						//ignore faces with oposite normals
801						if (normsum.lengthSq() > 0.001) {
802							mesh2.attributes.normals.setXYZ(i2, normsum.x, normsum.y, normsum.z);
803						}
804					}
805				}
806			}
807		}
808		console.log("merged bones:", mergecount);
809	}
