811	export function mergeModelDatas(models: ModelData[]) {
812		if (models.length == 0) {
813			return { bonecount: 0, skincount: 0, maxy: 0, miny: 0, meshes: [] };
814		}
815		const r: ModelData = {
816			bonecount: Math.max(...models.map(q => q.bonecount)),
817			skincount: Math.max(...models.map(q => q.skincount)),
818			maxy: Math.max(...models.map(q => q.maxy)),
819			miny: Math.max(...models.map(q => q.miny)),
820			meshes: models.flatMap(q => q.meshes),
821			debugmeshes: models.flatMap(q => q.debugmeshes ?? [])
822		}
823		return r;
824	}
