826	export async function ob3ModelToThree(scene: ThreejsSceneCache, model: ModelData, options: { noSkin?: boolean } = {}) {
827		const rootnode = new Object3D();
828		let nullskeleton: Skeleton = null!;
829		if (!options.noSkin && (model.bonecount != 0 || model.skincount != 0)) {
830			const nullbones: Object3D[] = [];
831			const maxbones = Math.max(model.bonecount, model.skincount);
832			const rootbone = new Bone();
833			rootnode.add(rootbone);
834			//TODO just need 2 skeletons here?
835			for (let i = 0; i < maxbones; i++) { nullbones.push(rootbone); }
836			nullskeleton = new Skeleton(nullbones as any);
837		}
838	
839		for (const meshdata of model.meshes) {
840			const attrs = meshdata.attributes;
841			const geo = new THREE.BufferGeometry();
842			geo.setAttribute("position", attrs.pos);
843			if (attrs.color) { geo.setAttribute("color", attrs.color); }
844			if (attrs.normals) { geo.setAttribute("normal", attrs.normals); }
845			if (attrs.texuvs) { geo.setAttribute("uv", attrs.texuvs); }
846			if (attrs.skinids) { geo.setAttribute("RA_skinIndex_skin", attrs.skinids); }
847			if (attrs.skinweights) { geo.setAttribute("RA_skinWeight_skin", attrs.skinweights); }
848			if (attrs.boneids) { geo.setAttribute("RA_skinIndex_bone", attrs.boneids); }
849			if (attrs.boneweights) { geo.setAttribute("RA_skinWeight_bone", attrs.boneweights); }
850			geo.index = meshdata.indices;
851			let mesh: THREE.Mesh | THREE.SkinnedMesh;
852			if (!options.noSkin && (attrs.skinids || attrs.boneids)) {
853				mesh = new THREE.SkinnedMesh(geo);
854				const oldbones = !!geo.attributes.RA_skinIndex_bone;
855				if (!geo.attributes.skinIndex) {
856					geo.attributes.skinIndex = (oldbones ? geo.attributes.RA_skinIndex_bone : geo.attributes.RA_skinIndex_skin);
857					geo.attributes.skinWeight = (oldbones ? geo.attributes.RA_skinWeight_bone : geo.attributes.RA_skinWeight_skin);
858				}
859				(mesh as SkinnedMesh).bind(nullskeleton);
860			} else {
861				mesh = new THREE.Mesh(geo);
862			}
863			applyMaterial(mesh, await scene.getMaterial(meshdata.materialId, meshdata.hasVertexAlpha, false), false);
864			rootnode.add(mesh);
865		}
866		if (model.debugmeshes && model.debugmeshes.length != 0) {
867			rootnode.add(...model.debugmeshes);
868		}
869		return rootnode;
870	}
