872	export function getModelHashes(model: models, id: number) {
873		const meshhashes: {
874			id: number,
875			sub: number,
876			uvshead: number,
877			uvsfull: number,
878			normalshead: number,
879			normalsfull: number,
880			poshead: number,
881			posfull: number,
882			verts: number,
883			indexpos: {
884				id: number,
885				head: number,
886				full: number,
887				count: number
888			}[]
889		}[] = [];
890		const matchvertices = 20;
891		const maxfullvertices = 1000;
892		const bufsize = matchvertices * 2 * 2;
893		const normalssize = matchvertices * 3;
894		const possize = matchvertices * 3 * 2;
895		if (!model.meshes) { throw new Error("model hash not supported for new model format"); }
896		for (const [sub, mesh] of model.meshes.entries()) {
897			let uvshead = 0;
898			let uvsfull = 0;
899			let normalshead = 0;
900			let normalsfull = 0;
901			let poshead = 0;
902			let posfull = 0;
903			if (mesh.uvBuffer && mesh.uvBuffer.length >= bufsize) {
904				let hasnonnull = false;
905				for (let i = 0; i < bufsize; i++) {
906					if (mesh.uvBuffer[i] != 0) {
907						hasnonnull = true;
908						break;
909					}
910				}
911				if (hasnonnull) {
912					uvshead = crc32(Buffer.from(mesh.uvBuffer.buffer, mesh.uvBuffer.byteOffset, bufsize));
913					uvsfull = crc32(Buffer.from(mesh.uvBuffer.buffer, mesh.uvBuffer.byteOffset, Math.min(maxfullvertices * 2 * 2, mesh.uvBuffer.byteLength)));
914				}
915			}
916			if (mesh.normalBuffer && mesh.normalBuffer.length >= normalssize) {
917				normalshead = crc32(Buffer.from(mesh.normalBuffer.buffer, mesh.normalBuffer.byteOffset, normalssize));
918				normalsfull = crc32(Buffer.from(mesh.normalBuffer.buffer, mesh.normalBuffer.byteOffset, Math.min(maxfullvertices * 3, mesh.normalBuffer.byteLength)));
919			}
920			if (mesh.positionBuffer && mesh.positionBuffer.length >= possize) {
921				poshead = crc32(Buffer.from(mesh.positionBuffer.buffer, mesh.positionBuffer.byteOffset, possize));
922				posfull = crc32(Buffer.from(mesh.positionBuffer.buffer, mesh.positionBuffer.byteOffset, Math.min(maxfullvertices * 3 * 2, mesh.positionBuffer.byteLength)));
923			}
924			const indexedposcrcs: { id: number, head: number, full: number, count: number }[] = [];
925			if (mesh.positionBuffer) {
926				for (const indices of mesh.indexBuffers) {
927					const primcount = indices.length / 3 | 0;
928					if (primcount >= matchvertices) {
929						const crc = new CrcBuilder();
930						let head = 0;
931						for (let i = 0; i < primcount; i++) {
932							for (let j = 0; j < 3; j++) {
933								const index = indices[i * 3 + j];
934								crc.addUint16(mesh.positionBuffer[index * 3 + 0]);
935								crc.addUint16(mesh.positionBuffer[index * 3 + 1]);
936								crc.addUint16(mesh.positionBuffer[index * 3 + 2]);
937							}
938							if (i == matchvertices - 1) {
939								head = crc.get();
940							}
941						}
942						indexedposcrcs.push({
943							id,
944							head,
945							full: crc.get(),
946							count: primcount
947						});
948					}
949				}
950			}
951			if (uvshead || poshead || normalshead || indexedposcrcs.length != 0) {
952				meshhashes.push({
953					id,
954					sub,
955					uvshead, uvsfull,
956					normalshead, normalsfull,
957					poshead, posfull,
958					verts: mesh.vertexCount!,
959					indexpos: indexedposcrcs
960				});
961			}
962		}
963	}
