20	export class SovereignGrounding {
21		varbits: Record<number, VarbitDefinition> = {};
22		mapzones: Record<number, MapZoneDefinition> = {};
23		synthesis: Record<number, { npcs: number[], objects: number[] }> = {};
24	
25		// Full Pedagogy Datasets for Interaction & POG2 Agent Runtime
26		pedagogy: {
27			enums: any;
28			dbtables: any;
29			materials: any;
30			quests: any;
31			equipment_by_slot: any;
32			objects: any;
33			items: any;
34			npcs: any;
35		} = { enums: {}, dbtables: {}, materials: {}, quests: {}, equipment_by_slot: {}, objects: {}, items: {}, npcs: {} };
36	
37		constructor(
38			varbits: Record<number, VarbitDefinition> = {}, 
39			mapzones: Record<number, MapZoneDefinition> = {}, 
40			synthesis: Record<number, { npcs: number[], objects: number[] }> = {},
41			pedagogy: any = {}
42		) {
43			this.varbits = varbits;
44			this.mapzones = mapzones;
45			this.synthesis = synthesis;
46			if (Object.keys(pedagogy).length > 0) {
47				this.pedagogy = pedagogy as any;
48			}
49		}
50	
51		findMapZone(x: number, z: number, plane: number): MapZoneDefinition | null {
52			for (const zone of Object.values(this.mapzones)) {
53				for (const bound of zone.bounds) {
54					if (bound.plane === plane &&
55						x >= bound.src.xstart && x <= bound.src.xend &&
56						z >= bound.src.zstart && z <= bound.src.zend) {
57						return zone;
58					}
59				}
60			}
61			return null;
62		}
63	
64		getVarbitsForBaseVar(baseVarId: number): Record<number, VarbitDefinition> {
65			const results: Record<number, VarbitDefinition> = {};
66			for (const [id, def] of Object.entries(this.varbits)) {
67				if (def.varid === baseVarId) {
68					results[+id] = def;
69				}
70			}
71			return results;
72		}
73	
74		getEntitiesForVarbit(varbitId: number): { npcs: number[], objects: number[] } {
75			return this.synthesis[varbitId] || { npcs: [], objects: [] };
76		}
77	
78		getRegionMetadata(x: number, z: number, plane: number = 0) {
79			const zone = this.findMapZone(x, z, plane);
80			if (!zone) return { id: -1, name: "Unknown Territory", archetype: "Wilderness" };
81			
82			return {
83				id: zone.center,
84				name: zone.name,
85				archetype: zone.internal_name,
86				varbits: [] // TODO: Collect varbits relevant to this zone
87			};
88		}
